mapper.update:
/* 보안코드 해시 저장(보안코드 필요 상태일 때만) */
UPDATE LGN_ATMPT_LMT
   SET SCRTY_CD_HASH = #{scrtyCdHash}
     , MDFCN_DT = NOW()
 WHERE LGN_ID_HMAC = #{lgnIdHmac}
   AND SCRTY_CD_RQT_YN = 'Y'

/* 보안코드 해시 비움 */
UPDATE LGN_ATMPT_LMT
   SET SCRTY_CD_HASH = NULL
     , MDFCN_DT = NOW()
 WHERE LGN_ID_HMAC = #{lgnIdHmac}

mapper.delete:
/* 로그인 실패 기록 삭제 */
DELETE FROM LGN_ATMPT_LMT
 WHERE LGN_ID_HMAC = #{lgnIdHmac}
